#!/usr/bin/env python3
"""Original solutions and task-specific scenes for exact 2023 exercises 446–461.
Printed pages 119–120 were visually inspected. Author checks are not independent approval.
"""
from copy import deepcopy
from pathlib import Path
import json, math
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'geometry-course/textbook'
EX,MODELS={},[]

def sc(ps=(),segs=(),**kw):return dict(label=kw.pop('label','Условие'),points=list(ps),segments=[list(x) for x in segs],**kw)
def tri(a='A',b='B',c='C'):return [[a,b],[b,c],[c,a]]
def eq(a,b,k=1):return dict(a=a,b=b,marks=k)
def rt(a,o,b):return dict(a=a,vertex=o,b=b,size=2.4)
def arc(o,a,b,k=0,r=6):return dict(vertex=o,**{'from':a,'to':b},marks=k,radius=r)
def ck(t,**kw):return dict(type=t,**kw)
def equal(*pairs):return ck('equalLength',segments=[list(x) for x in pairs])
def par(a,b,c,d):return ck('parallel',segments=[[a,b],[c,d]])
def perp(a,b,c,d):return ck('perpendicular',segments=[[a,b],[c,d]])
def col(*ps):return ck('collinear',points=list(ps))
def ang(a,o,b,d):return ck('angle',points=[a,o,b],degrees=d)
def ratio(a,b,c,d,r):return ck('distanceRatio',segments=[[a,b],[c,d]],ratio=r)
def row(q,e,r,refs):return (q,e,r,refs)
def mid(a,b):return [(a[i]+b[i])/2 for i in (0,1)]
def polar(o,t,r):return [o[0]+r*math.cos(math.radians(t)),o[1]+r*math.sin(math.radians(t))]
def dist(a,b):return math.hypot(a[0]-b[0],a[1]-b[1])
def foot(p,a,b):
 u=[b[i]-a[i] for i in (0,1)];t=sum((p[i]-a[i])*u[i] for i in (0,1))/sum(x*x for x in u)
 return [a[i]+t*u[i] for i in (0,1)]
def inter(a,b,c,d):
 u=[b[i]-a[i] for i in (0,1)];v=[d[i]-c[i] for i in (0,1)];den=u[0]*v[1]-u[1]*v[0]
 t=((c[0]-a[0])*v[1]-(c[1]-a[1])*v[0])/den
 return [a[i]+t*u[i] for i in (0,1)]
def circle(o,t):return dict(center=o,through=t)
def more(v,ps=(),segs=(),**kw):
 z=deepcopy(v);z['points']=list(dict.fromkeys(z.get('points',[])+list(ps)));z['segments']=z.get('segments',[])+[list(x) for x in segs];z.update(kw);return z
def case(v,label,unlock=1):return {**deepcopy(v),'label':label,'availableFromStep':unlock}
def normalize(points,views):
 allp=list(points.values())
 for v in views:
  for c in v.get('circles',[]):
   o=points[c['center']];r=dist(o,points[c['through']]);allp += [[o[0]-r,o[1]-r],[o[0]+r,o[1]+r]]
 xs=[p[0] for p in allp];ys=[p[1] for p in allp];s=min(76/(max(xs)-min(xs) or 1),56/(max(ys)-min(ys) or 1));cx=(max(xs)+min(xs))/2;cy=(max(ys)+min(ys))/2
 return {n:[round(50+(p[0]-cx)*s,9),round(42+(p[1]-cy)*s,9),0] for n,p in points.items()}
def variant(p,v,suffix,label,unlock=1):
 names={k:('_'+k[1:]+suffix if k.startswith('_') else k+suffix) for k in p}
 def ren(z):
  if isinstance(z,str):return names.get(z,z)
  if isinstance(z,list):return [ren(q) for q in z]
  if isinstance(z,dict):return {k:ren(val) for k,val in z.items()}
  return z
 vv=ren(v);vv.update(label=label,availableFromStep=unlock)
 return {names[k]:q for k,q in p.items()},vv,{names[k]:k for k in p if not k.startswith('_')}
def add(n,condition,answer,rows,p,neutral,views=None,checks=(),cases=(),labels=None,offsets=None,notes=(),groups=None):
 page=119 if n<=447 else 120
 EX[n]=dict(number=n,printedPages=[page],pdfPages=[page+1],parts=[dict(part='single',conditionSummary=condition,answer=answer,steps=[r[1] for r in rows],sourceVerified=True,mathVerified=True,visual=dict(initial='Данные условия. Искомые точки, ответ и вспомогательные линии открываются по шагам.',stepChanges=['Каждое построение появляется после его объяснения.'],cases=[v['label'] for v in cases]))],notes=list(notes),sourceChapter='IV' if n==446 else 'V')
 seq=views or [neutral]*len(rows);assert len(seq)==len(rows),(n,len(seq),len(rows))
 vv={'neutral':deepcopy(neutral)};vv.update({f'step-{i}':{**deepcopy(v),'label':f'Шаг {i}'} for i,v in enumerate(seq,1)});vv.update({f'case-{i}':deepcopy(v) for i,v in enumerate(cases,1)})
 pp=normalize(p,list(vv.values()))
 if groups:
  for names,vs in groups:pp.update(normalize({k:p[k] for k in names},vs))
 m=dict(points=pp,edges=[],planar=True,bounds=[0,0,100,84],views=vv,checks=list(checks),description=f'К задаче №{n}: отдельный авторский чертёж. Условия существования и доказательства находятся рядом.',labels={})
 if labels:m['labels'].update(labels)
 if offsets:m['labelOffsets']=offsets
 MODELS.append(dict(chapter='7-advanced',collection='main',number=n,part='single',model=m,didactics=dict(steps=[dict(prompt=r[0],justification=r[2],theoryPoints=r[3]) for r in rows])))

#446. Extend the base by the two adjacent sides; the new segment is the perimeter.
p={'D':[0,0],'E':[12,0]};p['A']=inter(p['D'],polar(p['D'],25,1),p['E'],polar(p['E'],145,1))
ax,ay=p['A'];p['B']=[(ax*ax+ay*ay)/(2*ax),0];p['C']=[((12*12)-(ax*ax+ay*ay))/(2*(12-ax)),0]
p['_b']=[p['B'][0]-ay,p['B'][1]+ax];p['_c']=[p['C'][0]-ay,p['C'][1]+ax-12]
b=sc('DE',[['D','E']]);v1=more(b,'A',[['D','A'],['E','A']],angleArcs=[arc('D','E','A'),arc('E','A','D')]);v2=more(v1,'B',lines=[['B','_b']],equalSegments=[eq('D','B'),eq('B','A')]);v3=more(v2,'C',[['B','A'],['C','A']],lines=[['B','_b'],['C','_c']],equalSegments=[eq('D','B'),eq('B','A'),eq('E','C',2),eq('C','A',2)]);fin=sc('ABCDE',[['D','B'],['B','C'],['C','E'],['A','B'],['A','C']],equalSegments=[eq('D','B'),eq('B','A'),eq('E','C',2),eq('C','A',2)])
add(446,'Постройте треугольник по заданному периметру p и двум углам. Обозначим эти углы при основании B и C через β и γ.','При p > 0, β > 0, γ > 0 и β + γ < 180° существует один треугольник с точностью до равенства.',[
 row('Какими должны быть заданные углы?','Проверь: p > 0, β > 0, γ > 0, β + γ < 180°. Третий угол равен 180° − β − γ. При нарушении условий невырожденного треугольника нет.','Сумма углов треугольника.',[31]),
 row('Как получить отрезок длиной во весь периметр?','Построй DE = p. Из D проведи луч под углом β/2 к DE, из E — луч под углом γ/2 к ED, в одну полуплоскость. Их пересечение обозначь A.','Биссектриса угла; сумма углов.',[22,31]),
 row('Как вернуть вершину B на отрезок DE?','Серединный перпендикуляр к AD пересечёт DE в B. Получено BA = BD. Точка B лежит между D и E.','Геометрическое место точек, равноудалённых от A и D.',[40]),
 row('Как найти вершину C?','Серединный перпендикуляр к AE пересечёт DE в C. Получено CA = CE. При β + γ < 180° точки расположены D, B, C, E в этом порядке. Проведи AB и AC.','Свойство серединного перпендикуляра; построение треугольника.',[40]),
 row('Почему углы и периметр правильные?','В равнобедренном ABD углы при A и D равны β/2, поэтому внешний угол ABC равен β. Аналогично ACB = γ. AB + BC + CA = DB + BC + CE = DE = p.','Внешний угол треугольника; равенство отрезков.',[18,31]),
 row('Почему другого по форме и размеру решения нет?','Для любого искомого треугольника продли BC: отложи BD = BA за B и CE = CA за C. Получится тот же треугольник DAE с DE = p и углами β/2, γ/2. Его равенство определяет A, а серединные перпендикуляры — B и C.','Второй признак равенства треугольников.',[19,40])],p,b,[b,v1,v2,v3,fin,fin],checks=[equal(('A','B'),('D','B')),equal(('A','C'),('E','C')),ang('A','B','C',50),ang('A','C','B',70),perp('A','D','B','_b'),perp('A','E','C','_c')])

#447. One, zero or infinitely many intersections with a perpendicular bisector.
p={'A':[-2,0],'B':[2,0],'M':[0,0],'U':[-3,2],'V':[3,2],'_l':[0,4],'X':[0,2]};b=sc('ABUV',[['A','B']],lines=[['U','V']]);v1=more(b,'M',lines=[['U','V'],['M','_l']]);fin=more(v1,'X',[['X','A'],['X','B']],equalSegments=[eq('X','A'),eq('X','B')]);cases=[];labs={}
for suffix,x,label in [('p',3,'Нет решения: параллельные разные прямые'),('i',0,'Бесконечно много: прямая совпала с серединным перпендикуляром')]:
 q={'A':[-2,0],'B':[2,0],'M':[0,0],'U':[x,-2],'V':[x,3],'_l':[0,3]};vv=sc('ABMUV',[['A','B']],lines=[['U','V'],['M','_l']]);qq,cv,ll=variant(q,vv,suffix,label,3);p.update(qq);cases.append(cv);labs.update(ll)
add(447,'Даны различные точки A и B и прямая a, не проходящая через них. Постройте на a точку, равноудалённую от A и B. Всегда ли она существует?','Искомые точки — пересечения a с серединным перпендикуляром к AB: одна, ни одной или бесконечно много.',[
 row('Где находятся все точки с XA = XB?','Построй середину M отрезка AB и прямую l через M, перпендикулярную AB. Это геометрическое место точек, равноудалённых от A и B.','Прямое и обратное свойства серединного перпендикуляра.',[40]),
 row('Как одновременно выполнить второе условие?','Если a пересекает l, обозначь точку пересечения X. Она лежит на a, а принадлежность l даёт XA = XB.','Пересечение двух геометрических мест.',[40]),
 row('Когда единственного пересечения нет?','Если a параллельна l и не совпадает с ней, решений нет. Если a = l, подходит любая точка a. Все три случая согласуются с тем, что a не проходит через A и B.','Взаимное расположение прямых.',[24,40])],p,b,[v1,fin,fin],checks=[equal(('X','A'),('X','B')),perp('A','B','M','_l')],cases=cases,labels=labs)

